//! Byte-for-byte comparison of the `[PACKET]` section against captured
//! `ffprobe` output.
//!
//! GENERATED BY OBSERVATION, NOT BY HAND. Reference: `ffprobe version 8.1`
//! (Homebrew, arm64 macOS, 2026), `libavformat 62.12.100`, under `LC_ALL=C`.
//!
//! The sample file:
//!
//! ```sh
//! ffmpeg -f lavfi -i testsrc2=size=320x240:rate=25:duration=2 \
//!        -f lavfi -i sine=frequency=440:duration=2 \
//!        -c:v libx264 -pix_fmt yuv420p -c:a aac -shortest av.mp4
//!
//! ffprobe -v quiet -of default -show_packets -read_intervals '%+#4' av.mp4
//! ffprobe -v quiet -of json    -show_packets -read_intervals '%+#2' av.mp4
//! ffprobe -v quiet -of compact -show_packets -read_intervals '%+#3' av.mp4
//! ```
//!
//! # Why the packets are replayed rather than demuxed
//!
//! Same reason as `reference.rs`: this file is about **which fields, in what
//! order, spelled how**, and mixing a demuxer into that would make every
//! demuxer change a failure here. [`av_mp4_packets`] builds the `Packet`
//! values a correct MP4 demuxer produces, taken from the same `ffprobe` run —
//! and `vaco-demux-mp4` does in fact produce exactly these, verified
//! end-to-end at 2 431 of 2 431 field values across six MP4/MOV files. The
//! divergences that remain live in Matroska and MPEG-TS and are recorded in
//! `docs/app/vaco-probe.md`, not here.

#![allow(
    clippy::expect_used,
    reason = "a test that cannot set up is a failed test"
)]

use vaco_core::{Duration, MediaType, Rational, Timestamp};
use vaco_format_core::Stream;
use vaco_limits::{Budget, Limits};
use vaco_packet::{Packet, PacketFlags, PacketSideData};
use vaco_probe::dump::{DumpFormat, HashAlg};
use vaco_probe::emit::Emit;
use vaco_probe::show::{self, PayloadOpts};
use vaco_textformat::sections::SectionId;
use vaco_textformat::{FormatOpts, OptionalFields, TextFormat, writers};

// ------------------------------------------------------------ captured bytes

