/// `ffprobe -v quiet -of compact -show_packets -read_intervals '%+#3' av.mp4`
///
/// The third line is the one worth having: packet side data inlines into the
/// packet's own line as `side_datum/<sanitised type>:<field>`.
const PACKETS_COMPACT: &str = "\
packet|codec_type=video|stream_index=0|pts=0|pts_time=0.000000|dts=-1024|dts_time=-0.080000|duration=512|duration_time=0.040000|size=5171|pos=48|flags=K__
packet|codec_type=video|stream_index=0|pts=2048|pts_time=0.160000|dts=-512|dts_time=-0.040000|duration=512|duration_time=0.040000|size=2456|pos=5219|flags=___
packet|codec_type=audio|stream_index=1|pts=-1024|pts_time=-0.023220|dts=-1024|dts_time=-0.023220|duration=1024|duration_time=0.023220|size=258|pos=7675|flags=KD_|side_datum/skip_samples:side_data_type=Skip Samples|side_datum/skip_samples:skip_samples=1024|side_datum/skip_samples:discard_padding=0|side_datum/skip_samples:skip_reason=0|side_datum/skip_samples:discard_reason=0
";

/// `-pretty`, which is the run that caught `pos`.
///
/// ```sh
/// ffprobe -v error -of csv=p=0:nk=1 -show_entries packet=size,pos \
///         -unit -prefix -show_packets -read_intervals '%+#1' av.mp4
/// ```
///
/// prints `5.171000 Kbyte,48`. `size` scales and takes a unit; `pos` — the
/// next column, also a byte count — does neither.
const PRETTY_SIZE_AND_POS: &str = "5.171000 Kbyte|48";

// ------------------------------------------------------------- the input

fn av_mp4_streams() -> Vec<Stream> {
    let mut v = Stream::new(0, MediaType::Video, Rational { num: 1, den: 12800 });
    v.index = 0;
    let mut a = Stream::new(1, MediaType::Audio, Rational { num: 1, den: 44100 });
    a.index = 1;
    vec![v, a]
}

/// The first four packets of `av.mp4`, exactly as `ffprobe` reports them.
fn av_mp4_packets() -> Vec<Packet> {
    vec![
        pkt(0, 0, -1024, 512, 5171, 48, PacketFlags::KEY),
        pkt(0, 2048, -512, 512, 2456, 5219, PacketFlags::empty()),
        {
            let mut p = pkt(
                1,
                -1024,
                -1024,
                1024,
                258,
                7675,
                PacketFlags::KEY | PacketFlags::DISCARD,
            );
            p.side_data.push(PacketSideData::SkipSamples {
                start: 1024,
                end: 0,
            });
            p
        },
        pkt(0, 1024, 0, 512, 1428, 7933, PacketFlags::empty()),
    ]
}

/// `duration` is given in the stream's own ticks and converted to the
/// microsecond `Duration` the model carries, which is what a demuxer does.
fn pkt(
    stream: u32,
    pts: i64,
    dts: i64,
    duration_ticks: i64,
    size: usize,
    pos: u64,
    flags: PacketFlags,
) -> Packet {
    let tb = if stream == 0 {
        Rational { num: 1, den: 12800 }
    } else {
        Rational { num: 1, den: 44100 }
    };
    let mut p = Packet::alloc(&mut Budget::new(Limits::permissive()), size).expect("payload");
    p.stream_index = stream;
    p.pts = Timestamp::new(pts);
    p.dts = Timestamp::new(dts);
    p.duration = Timestamp::new(duration_ticks)
        .to_duration(tb)
        .unwrap_or(Duration::ZERO);
    p.pos = Some(pos);
    p.flags = flags;
    p
}

// ------------------------------------------------------------------ harness

fn render(spec: &str, take: usize, payload: PayloadOpts) -> String {
    let streams = av_mp4_streams();
    let mut sink = Vec::new();
    {
        let w = writers::make(spec).expect("writer");
        let mut tf = TextFormat::new(w, &mut sink, FormatOpts::default());
        tf.open(SectionId::ROOT).expect("root");
        {
            let mut e = Emit::new(&mut tf, OptionalFields::Auto);
            e.tf().open(SectionId::PACKETS).expect("packets");
            for p in av_mp4_packets().iter().take(take) {
                let s = streams.iter().find(|s| s.index == p.stream_index);
                show::packet(&mut e, p, s, payload).expect("packet");
            }
            e.tf().close().expect("close packets");
        }
        tf.close().expect("close root");
        let _ = tf.finish().expect("finish");
    }
    String::from_utf8(sink).expect("utf-8")
}

// -------------------------------------------------------------------- tests

#[test]
fn the_default_writer_is_byte_identical() {
    assert_eq!(
        render("default", 4, PayloadOpts::default()),
        PACKETS_DEFAULT
    );
}

#[test]
fn the_json_writer_is_byte_identical_including_the_quoting() {
    // The quoting is the point: `pts` and `duration` are bare numbers,
    // `size` and `pos` are quoted strings holding numbers, three fields apart.
    assert_eq!(render("json", 2, PayloadOpts::default()), PACKETS_JSON);
}

#[test]
fn the_compact_writer_inlines_packet_side_data() {
    assert_eq!(
        render("compact", 3, PayloadOpts::default()),
        PACKETS_COMPACT
    );
}

#[test]
fn size_scales_under_pretty_and_pos_does_not() {
    // The regression this exists for: `pos` was typed as a byte *value* and
    // printed `5.219000 Kbyte`. It is a plain integer string.
    let streams = av_mp4_streams();
    let mut sink = Vec::new();
    {
        let w = writers::make("compact=p=0:nk=1").expect("writer");
        let mut tf = TextFormat::new(w, &mut sink, FormatOpts::pretty());
        tf.open(SectionId::ROOT).expect("root");
        {
            let mut e = Emit::new(&mut tf, OptionalFields::Auto);
            let packets = av_mp4_packets();
            let p = packets.first().expect("one packet");
            show::packet(&mut e, p, streams.first(), PayloadOpts::default()).expect("packet");
        }
        tf.close().expect("close");
        let _ = tf.finish().expect("finish");
    }
    let line = String::from_utf8(sink).expect("utf-8");
    let fields: Vec<&str> = line.trim_end().split('|').collect();
    // size and pos are the ninth and tenth fields.
    let got = format!(
        "{}|{}",
        fields.get(8).copied().unwrap_or_default(),
        fields.get(9).copied().unwrap_or_default()
    );
    assert_eq!(got, PRETTY_SIZE_AND_POS);
}

#[test]
fn show_data_puts_the_dump_after_flags_and_before_the_hash() {
    // Both fields on at once; the reference emits `data` first. Observed with
    // `-show_data -show_data_hash CRC32`.
    let out = render(
        "default",
        1,
        PayloadOpts {
            data: Some(DumpFormat::Base64),
            hash: Some(HashAlg::Crc32),
        },
    );
    let flags = out.find("flags=").expect("flags");
    let data = out.find("data=").expect("data");
    let hash = out.find("data_hash=").expect("data_hash");
    assert!(flags < data && data < hash, "{out}");
}

#[test]
fn a_packet_with_no_timestamps_prints_the_placeholders() {
    // A raw H.264 stream has neither pts nor dts. Observed:
    // `ffprobe -v error -of default -show_packets bt709.264` prints
    // `pts=N/A` / `pts_time=N/A` and a real `duration`.
    let streams = av_mp4_streams();
    let mut sink = Vec::new();
    {
        let w = writers::make("default").expect("writer");
        let mut tf = TextFormat::new(w, &mut sink, FormatOpts::default());
        tf.open(SectionId::ROOT).expect("root");
        {
            let mut e = Emit::new(&mut tf, OptionalFields::Auto);
            let mut p = Packet::alloc(&mut Budget::new(Limits::permissive()), 10).expect("payload");
            p.pos = Some(0);
            show::packet(&mut e, &p, streams.first(), PayloadOpts::default()).expect("packet");
        }
        tf.close().expect("close");
        let _ = tf.finish().expect("finish");
    }
    let out = String::from_utf8(sink).expect("utf-8");
    assert!(out.contains("pts=N/A\n"), "{out}");
    assert!(out.contains("pts_time=N/A\n"), "{out}");
    // A duration of zero prints N/A, unlike a pts of zero. Measured.
    assert!(out.contains("duration=N/A\n"), "{out}");
    assert!(out.contains("duration_time=N/A\n"), "{out}");
    assert!(out.contains("flags=___\n"), "{out}");
}

#[test]
fn the_three_flag_characters_are_key_discard_corrupt_in_that_order() {
    // Measured on three files: MP4's first AAC packet is `KD_` (discard, from
    // the encoder delay), an MPEG-TS file with one 188-byte packet removed
    // gives `K_C` on the packet spanning the gap, and everything else is
    // `K__` or `___`. So the middle character is D and the last is C — the
    // opposite order to the `PacketFlags` bit numbering, which is
    // KEY/CORRUPT/DISCARD.
    for (flags, want) in [
        (PacketFlags::empty(), "___"),
        (PacketFlags::KEY, "K__"),
        (PacketFlags::KEY | PacketFlags::DISCARD, "KD_"),
        (PacketFlags::KEY | PacketFlags::CORRUPT, "K_C"),
        (PacketFlags::DISCARD | PacketFlags::CORRUPT, "_DC"),
    ] {
        let streams = av_mp4_streams();
        let mut sink = Vec::new();
        {
            let w = writers::make("csv=p=0:nk=1").expect("writer");
            let mut tf = TextFormat::new(w, &mut sink, FormatOpts::default());
            tf.open(SectionId::ROOT).expect("root");
            {
                let mut e = Emit::new(&mut tf, OptionalFields::Auto);
                let mut p =
                    Packet::alloc(&mut Budget::new(Limits::permissive()), 4).expect("payload");
                p.pos = Some(0);
                p.flags = flags;
                show::packet(&mut e, &p, streams.first(), PayloadOpts::default()).expect("packet");
            }
            tf.close().expect("close");
            let _ = tf.finish().expect("finish");
        }
        let out = String::from_utf8(sink).expect("utf-8");
        assert!(out.trim_end().ends_with(want), "{flags:?}: {out}");
    }
}

#[test]
fn show_frames_fails_loudly_rather_than_printing_an_empty_section() {
    // The whole point of the work this file belongs to. An empty `[FRAMES]`
    // array and exit 0 is indistinguishable from "this file has no frames",
    // and a differential harness records it as a pass.
    for flag in ["-show_frames", "-count_frames"] {
        let (mut out, mut err) = (Vec::new(), Vec::new());
        let exit = vaco_probe::run(&[flag, "nonexistent.mp4"], &mut out, &mut err);
        assert_eq!(exit, vaco_probe::Exit::Failure, "{flag}");
        assert!(out.is_empty(), "{flag} wrote to stdout");
        let err = String::from_utf8_lossy(&err);
        assert!(err.contains("need a decoder"), "{flag}: {err}");
        // The message names where the work went, as `vaco-cli`'s ENOSYS does.
        assert!(err.contains("D14.4"), "{flag}: {err}");
    }
}

#[test]
fn an_unimplemented_hash_fails_loudly_rather_than_omitting_the_field() {
    // `data_hash` is `Absent::Omit`, so a `digest` that returns `None` would
    // print an ordinary packet with no `data_hash` line and exit 0 — the same
    // silent-success shape.
    let (mut out, mut err) = (Vec::new(), Vec::new());
    let exit = vaco_probe::run(
        &["-show_packets", "-show_data_hash", "RIPEMD160", "x.mp4"],
        &mut out,
        &mut err,
    );
    assert_eq!(exit, vaco_probe::Exit::Failure);
    let err = String::from_utf8_lossy(&err);
    assert!(err.contains("RIPEMD"), "{err}");

    // The ten that do work are not affected.
    let (mut out, mut err) = (Vec::new(), Vec::new());
    let exit = vaco_probe::run(
        &[
            "-show_packets",
            "-show_data_hash",
            "SHA256",
            "nonexistent.mp4",
        ],
        &mut out,
        &mut err,
    );
    assert_eq!(exit, vaco_probe::Exit::Failure, "the file is still missing");
    assert!(
        !String::from_utf8_lossy(&err).contains("RIPEMD"),
        "SHA256 must not be refused"
    );
}
